def ciur(n):
    este_prim = [True] * (n + 1)
    este_prim[0] = este_prim[1] = False
    for p in range(2, int(n ** 0.5) + 1):
        if este_prim[p]:
            for m in range(p * p, n + 1, p):
                este_prim[m] = False
    return [i for i in range(2, n + 1) if este_prim[i]]

