import heapq

def dijkstra(graf, start):
    dist = {start: 0}
    coada = [(0, start)]
    while coada:
        d, v = heapq.heappop(coada)
        for u, w in graf.get(v, []):
            if u not in dist or d + w < dist[u]:
                dist[u] = d + w
                heapq.heappush(coada, (dist[u], u))
    return dist

