import heapq

def prim(graf, start):
    viz = {start}
    muchii = [(w, start, u) for u, w in graf[start]]
    heapq.heapify(muchii)
    total = 0
    while muchii:
        w, a, b = heapq.heappop(muchii)
        if b in viz:
            continue
        viz.add(b)
        total += w
        for u, w2 in graf[b]:
            if u not in viz:
                heapq.heappush(muchii, (w2, b, u))
    return total

